"""`harness tune` — friction analysis over recent sessions.

Reads the last N session JSONLs in a project, aggregates per-slash-command
friction (interventions, blocked signals, repeat-within-session, duration),
applies threshold rules, and emits a markdown hotspot report.

Read-only. No skill-body edits. No state-file writes. Strategy-aligned:
Harness observes signals; the team owns content changes.
"""

from __future__ import annotations

from datetime import datetime
from pathlib import Path

from jinja2 import Environment, FileSystemLoader, StrictUndefined
from rich.console import Console
from rich.table import Table

from harness.analyse.aggregator import analyse
from harness.analyse.parser import list_project_sessions, parse_session
from harness.analyse.tuning import (
    CommandFriction,
    HotspotFlag,
    TuningThresholds,
    compute_friction,
    find_hotspots,
    project_median_duration,
    render_recommendations,
)

_CLAUDE_PROJECTS_ROOT = Path.home() / ".claude" / "projects"
_TEMPLATE_DIR = Path(__file__).parent.parent / "analyse" / "templates"

_console = Console()
_err = Console(stderr=True)


def cmd_tune(
    *,
    project: str | None,
    last: int,
    out_path: Path,
    threshold_interventions: float,
    threshold_blocked: float,
    threshold_intervention_rate: float,
) -> int:
    """Aggregate friction across recent sessions; emit a tuning report."""
    proj_dir = _resolve_project(project)
    if proj_dir is None:
        return 1

    session_paths = list_project_sessions(proj_dir)
    if not session_paths:
        _err.print(f"[red]no sessions under {proj_dir}[/red]")
        return 1

    # `list_project_sessions` returns newest-first; take the last N.
    targets = session_paths[:last]
    _console.print(f"[dim]aggregating[/dim] {len(targets)} session(s) under {proj_dir}")

    analyses = []
    for target in targets:
        try:
            sess = parse_session(target)
            analyses.append(analyse(sess))
        except Exception as exc:
            _err.print(f"[yellow]skip {target.name}: {exc}[/yellow]")
            continue

    if not analyses:
        _err.print("[red]no sessions could be parsed[/red]")
        return 1

    frictions = compute_friction(analyses)
    if not frictions:
        _err.print("[yellow]no slash-commands observed in the sample[/yellow]")
        return 1

    thresholds = TuningThresholds(
        mean_interventions_per_run=threshold_interventions,
        intervention_rate=threshold_intervention_rate,
        blocked_rate=threshold_blocked,
    )
    median_dur = project_median_duration(frictions)
    flags = find_hotspots(frictions, thresholds=thresholds, project_median_duration=median_dur)
    recommendations = render_recommendations(flags)

    report = _render_report(
        project_slug=proj_dir.name,
        session_count=len(analyses),
        frictions=frictions,
        flags=flags,
        recommendations=recommendations,
        thresholds=thresholds,
        median_duration=median_dur,
    )

    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(report, encoding="utf-8")
    _console.print(f"[green]wrote[/green] tuning report → {out_path}")
    _print_summary_table(frictions, flags)
    return 0


def _render_report(
    *,
    project_slug: str,
    session_count: int,
    frictions: list[CommandFriction],
    flags: list[HotspotFlag],
    recommendations: list[str],
    thresholds: TuningThresholds,
    median_duration: float,
) -> str:
    env = Environment(
        loader=FileSystemLoader(str(_TEMPLATE_DIR)),
        autoescape=False,
        undefined=StrictUndefined,
        trim_blocks=True,
        lstrip_blocks=True,
    )
    tmpl = env.get_template("tuning.md.j2")
    return tmpl.render(
        project_slug=project_slug,
        generated_at=datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        session_count=session_count,
        frictions=frictions,
        flags=flags,
        recommendations=recommendations,
        thresholds=thresholds,
        median_duration=median_duration,
    )


def _print_summary_table(frictions: list[CommandFriction], flags: list[HotspotFlag]) -> None:
    """Show the user a quick rich-table summary in the terminal."""
    tbl = Table(show_header=True, header_style="bold", title="Top hotspots")
    tbl.add_column("Rank", justify="right")
    tbl.add_column("Command")
    tbl.add_column("Friction", justify="right")
    tbl.add_column("Interv/run", justify="right")
    tbl.add_column("Blocked%", justify="right")
    tbl.add_column("Repeat%", justify="right")

    flagged_commands = {f.command for f in flags}
    ranked = sorted(frictions, key=lambda c: c.friction_score, reverse=True)[:10]
    for i, cf in enumerate(ranked, 1):
        marker = " ⚠" if cf.command in flagged_commands else ""
        tbl.add_row(
            str(i),
            cf.command + marker,
            f"{cf.friction_score:.2f}",
            f"{cf.mean_interventions_per_run:.1f}",
            f"{cf.blocked_rate * 100:.0f}%",
            f"{cf.repeat_rate * 100:.0f}%",
        )
    _console.print(tbl)


def _resolve_project(project: str | None) -> Path | None:
    if not project:
        # Default to cwd-derived slug.
        slug = _slug_for(Path.cwd())
        guess = _CLAUDE_PROJECTS_ROOT / slug
        if not guess.is_dir():
            _err.print(
                f"[red]no project at {guess}; pass --project or run from a project root[/red]"
            )
            return None
        return guess
    if project.startswith("-Users-"):
        return _CLAUDE_PROJECTS_ROOT / project
    path = Path(project).expanduser().resolve()
    if path.is_dir() and path.parent == _CLAUDE_PROJECTS_ROOT:
        return path
    # Try as substring of slug.
    candidates = [p for p in _CLAUDE_PROJECTS_ROOT.iterdir() if project in p.name]
    if len(candidates) == 1:
        return candidates[0]
    if len(candidates) > 1:
        _err.print(f"[red]ambiguous project {project!r}; got {len(candidates)} matches[/red]")
        return None
    _err.print(f"[red]no project matching {project!r}[/red]")
    return None


def _slug_for(path: Path) -> str:
    """Convert an absolute path to the slug Claude Code uses for project dirs.
    `/`, `.`, and space all become `-` (matches the runtime's transform).
    Matches the implementation in `commands.analyse._slug_for`.
    """
    s = str(path.resolve()).lstrip("/")
    return "-" + s.replace("/", "-").replace(".", "-").replace(" ", "-")
